WITH v(title, description, ingredients, steps, prep, cook, servings, cuisine, diet, calories, meal_types) AS (VALUES
  ('Greek Chicken Bowls', 'Lemon-oregano chicken over herbed rice with cucumber, tomato and tzatziki.', '["2 chicken breasts","1 cup long-grain rice","1 lemon","2 tsp dried oregano","1 cucumber","2 tomatoes","1/2 red onion","1/2 cup tzatziki","Olive oil, salt, pepper"]'::jsonb, '["Marinate chicken in lemon juice, oregano, olive oil, salt and pepper for 15 minutes.","Cook rice according to package directions.","Grill or pan-sear chicken 6–7 minutes per side, then rest and slice.","Dice cucumber, tomatoes and onion.","Build bowls with rice, chicken and vegetables; top with tzatziki."]'::jsonb, 15, 25, 4, 'Mediterranean', 'Omnivore', 520, ARRAY['lunch', 'dinner']::text[]),
  ('Salmon Teriyaki with Greens', 'Glazed salmon fillets with garlicky bok choy and jasmine rice.', '["4 salmon fillets","1/3 cup teriyaki sauce","1 tbsp honey","2 heads bok choy","2 cloves garlic","1 cup jasmine rice","Sesame seeds","Spring onion"]'::jsonb, '["Cook the rice.","Whisk teriyaki sauce with honey.","Sear salmon skin-side down 4 minutes, flip, brush with glaze and cook 3 more minutes.","Stir-fry bok choy with garlic for 3 minutes.","Serve salmon over rice with greens; garnish with sesame and spring onion."]'::jsonb, 10, 20, 4, 'Japanese', 'Pescatarian', 560, ARRAY['lunch', 'dinner']::text[]),
  ('Chickpea Coconut Curry', 'A creamy, warming curry that comes together in one pot.', '["2 cans chickpeas","1 can coconut milk","1 can diced tomatoes","1 onion","3 cloves garlic","1 tbsp ginger","2 tbsp curry powder","2 cups spinach","Rice or naan to serve"]'::jsonb, '["Sauté onion until soft, then add garlic, ginger and curry powder for 1 minute.","Add tomatoes, coconut milk and chickpeas; simmer 15 minutes.","Stir in spinach until wilted.","Season and serve with rice or naan."]'::jsonb, 10, 25, 4, 'Indian', 'Vegan', 480, ARRAY['lunch', 'dinner']::text[]),
  ('Turkey Taco Lettuce Wraps', 'Light, crunchy tacos with seasoned ground turkey.', '["1 lb ground turkey","1 tbsp taco seasoning","1 head butter lettuce","1 cup pico de gallo","1 avocado","1/2 cup shredded cheese","1 lime"]'::jsonb, '["Brown turkey with taco seasoning and a splash of water.","Separate lettuce leaves into cups.","Fill with turkey, pico de gallo, avocado and cheese.","Finish with a squeeze of lime."]'::jsonb, 10, 12, 4, 'Mexican', 'Omnivore', 380, ARRAY['lunch', 'dinner']::text[]),
  ('Mediterranean Quinoa Salad', 'Bright quinoa salad with feta, olives and a lemon vinaigrette.', '["1 cup quinoa","1 cucumber","1 cup cherry tomatoes","1/2 cup kalamata olives","1/2 cup feta","1/4 cup parsley","1 lemon","3 tbsp olive oil"]'::jsonb, '["Cook quinoa and let it cool.","Chop cucumber, tomatoes, olives and parsley.","Whisk lemon juice with olive oil, salt and pepper.","Toss everything together and top with feta."]'::jsonb, 15, 15, 4, 'Mediterranean', 'Vegetarian', 410, ARRAY['lunch']::text[]),
  ('Overnight Oats with Berries', 'Make-ahead breakfast with oats, chia and fresh berries.', '["1/2 cup rolled oats","1/2 cup milk or oat milk","1/4 cup Greek yogurt","1 tbsp chia seeds","1 tsp maple syrup","1/2 cup mixed berries"]'::jsonb, '["Stir oats, milk, yogurt, chia and maple syrup together in a jar.","Refrigerate overnight.","Top with berries in the morning."]'::jsonb, 5, 0, 1, 'American', 'Vegetarian', 350, ARRAY['breakfast']::text[]),
  ('Beef and Broccoli Stir-Fry', 'Takeout-style beef and broccoli in a savory garlic sauce.', '["1 lb flank steak","4 cups broccoli florets","3 tbsp soy sauce","1 tbsp oyster sauce","1 tbsp cornstarch","2 cloves garlic","1 tsp ginger","Rice to serve"]'::jsonb, '["Slice steak thinly against the grain and toss with 1 tbsp soy sauce and cornstarch.","Sear beef in batches over high heat; set aside.","Stir-fry broccoli 3 minutes with garlic and ginger.","Return beef, add remaining soy and oyster sauce, toss 1 minute.","Serve over rice."]'::jsonb, 15, 15, 4, 'Chinese', 'Omnivore', 540, ARRAY['lunch', 'dinner']::text[]),
  ('Black Bean Sweet Potato Tacos', 'Roasted sweet potato and smoky black beans in warm tortillas.', '["2 sweet potatoes","1 can black beans","1 tsp smoked paprika","1 tsp cumin","8 corn tortillas","1 avocado","1/4 cup cilantro","1 lime"]'::jsonb, '["Dice sweet potatoes, toss with oil, paprika and cumin; roast at 425°F for 25 minutes.","Warm black beans with a pinch of cumin.","Warm tortillas.","Fill with sweet potato, beans, avocado and cilantro; add lime."]'::jsonb, 10, 25, 4, 'Mexican', 'Vegan', 430, ARRAY['lunch', 'dinner']::text[]),
  ('Shrimp Scampi Zoodles', 'Garlic-butter shrimp tossed with zucchini noodles.', '["1 lb shrimp","4 zucchini, spiralized","4 cloves garlic","2 tbsp butter","1 lemon","1/4 tsp chili flakes","Parsley","Parmesan"]'::jsonb, '["Melt butter and sauté garlic with chili flakes for 1 minute.","Add shrimp and cook 2 minutes per side.","Add zucchini noodles and lemon juice; toss 2 minutes.","Finish with parsley and parmesan."]'::jsonb, 15, 10, 4, 'Italian', 'Pescatarian', 320, ARRAY['lunch', 'dinner']::text[]),
  ('Lentil Bolognese', 'Hearty plant-based bolognese over whole-wheat pasta.', '["1 cup brown lentils","1 onion","2 carrots","2 celery stalks","3 cloves garlic","1 can crushed tomatoes","2 tbsp tomato paste","12 oz whole-wheat spaghetti","Italian seasoning"]'::jsonb, '["Finely dice onion, carrot and celery; sauté 8 minutes.","Add garlic and tomato paste for 1 minute.","Add lentils, tomatoes, seasoning and 2 cups water; simmer 30 minutes.","Cook pasta and toss with the sauce."]'::jsonb, 15, 40, 6, 'Italian', 'Vegan', 460, ARRAY['dinner']::text[]),
  ('Egg & Veggie Breakfast Scramble', 'Protein-packed scramble with peppers, spinach and feta.', '["4 eggs","1 bell pepper","1 cup spinach","1/4 cup feta","1/4 onion","Whole-grain toast"]'::jsonb, '["Sauté onion and pepper until soft.","Add spinach until wilted.","Pour in whisked eggs and stir gently until just set.","Top with feta and serve with toast."]'::jsonb, 5, 10, 2, 'American', 'Vegetarian', 330, ARRAY['breakfast']::text[]),
  ('Sheet-Pan Lemon Herb Chicken', 'Chicken thighs roasted with potatoes and green beans on one pan.', '["6 chicken thighs","1 lb baby potatoes","8 oz green beans","1 lemon","3 cloves garlic","1 tbsp rosemary","Olive oil, salt, pepper"]'::jsonb, '["Heat oven to 425°F.","Toss halved potatoes with oil, salt and rosemary; roast 15 minutes.","Add chicken rubbed with garlic, lemon zest and oil; roast 20 minutes.","Add green beans and lemon slices; roast 10 more minutes."]'::jsonb, 15, 45, 4, 'American', 'Omnivore', 590, ARRAY['dinner']::text[]),
  ('Tofu Pad Thai', 'Sweet, tangy rice noodles with crispy tofu and peanuts.', '["8 oz rice noodles","14 oz firm tofu","3 tbsp tamari","2 tbsp lime juice","2 tbsp brown sugar","1 cup bean sprouts","3 spring onions","1/4 cup peanuts"]'::jsonb, '["Soak noodles in hot water until pliable.","Press and cube tofu; pan-fry until golden.","Whisk tamari, lime juice and sugar.","Toss noodles with sauce, tofu and sprouts over high heat for 2 minutes.","Top with spring onions and crushed peanuts."]'::jsonb, 20, 15, 4, 'Thai', 'Vegan', 510, ARRAY['lunch', 'dinner']::text[]),
  ('Tuna Poke Bowl', 'Fresh sushi-grade tuna with rice, edamame and avocado.', '["12 oz sushi-grade tuna","2 tbsp soy sauce","1 tsp sesame oil","2 cups sushi rice","1 cup edamame","1 avocado","1 cucumber","Pickled ginger, nori"]'::jsonb, '["Cook and cool the rice.","Cube tuna and toss with soy sauce and sesame oil.","Slice avocado and cucumber.","Assemble bowls with rice, tuna, edamame, avocado and cucumber; garnish with ginger and nori."]'::jsonb, 20, 20, 2, 'Japanese', 'Pescatarian', 610, ARRAY['lunch', 'dinner']::text[]),
  ('Caprese Stuffed Portobellos', 'Roasted mushrooms filled with tomato, mozzarella and basil.', '["4 portobello caps","1 cup cherry tomatoes","4 oz fresh mozzarella","Fresh basil","2 tbsp balsamic glaze","Olive oil"]'::jsonb, '["Heat oven to 400°F; brush mushrooms with oil.","Fill with halved tomatoes and mozzarella.","Roast 15 minutes.","Top with basil and balsamic glaze."]'::jsonb, 10, 15, 4, 'Italian', 'Vegetarian', 240, ARRAY['lunch', 'dinner']::text[]),
  ('Rainbow Raw Veggie Wraps', 'No-cook collard wraps with hummus and crunchy vegetables.', '["4 large collard leaves","1/2 cup hummus","1 carrot","1 red pepper","1/2 red cabbage","1 avocado","Sprouts"]'::jsonb, '["Trim collard stems so leaves lie flat.","Spread hummus down the center.","Layer julienned vegetables, avocado and sprouts.","Roll tightly like a burrito and slice in half."]'::jsonb, 15, 0, 2, 'American', 'Raw', 290, ARRAY['lunch']::text[]),
  ('Chicken Fajita Sheet Pan', 'Smoky chicken, peppers and onions roasted together and piled into warm tortillas.', '["1.5 lb chicken breast, sliced","3 bell peppers","1 red onion","2 tbsp olive oil","1 tbsp fajita seasoning","8 flour tortillas","1 lime","Sour cream and salsa"]'::jsonb, '["Heat oven to 425°F.","Toss chicken, sliced peppers and onion with oil and seasoning on a sheet pan.","Roast 20–25 minutes until the chicken is cooked through.","Squeeze lime over the pan and serve in warm tortillas with sour cream and salsa."]'::jsonb, 15, 25, 4, 'Mexican', 'Omnivore', 490, ARRAY['lunch', 'dinner']::text[]),
  ('Turkey Meatballs with Marinara', 'Tender herbed turkey meatballs simmered in a quick tomato sauce.', '["1 lb ground turkey","1/3 cup breadcrumbs","1 egg","1/4 cup parmesan","2 cloves garlic","1 tsp Italian seasoning","24 oz marinara","Fresh basil"]'::jsonb, '["Mix turkey, breadcrumbs, egg, parmesan, garlic and seasoning; roll into 16 balls.","Brown meatballs in an oiled skillet, about 6 minutes.","Add marinara, cover and simmer 15 minutes.","Top with basil; serve over pasta or with crusty bread."]'::jsonb, 20, 25, 4, 'Italian', 'Omnivore', 450, ARRAY['dinner']::text[]),
  ('Korean Beef Rice Bowls', 'Sweet-savory ground beef with garlic and ginger over rice with quick-pickled cucumbers.', '["1 lb lean ground beef","3 tbsp soy sauce","2 tbsp brown sugar","1 tbsp sesame oil","3 cloves garlic","1 tsp ginger","2 cups cooked rice","1 cucumber","Rice vinegar","Spring onions"]'::jsonb, '["Toss sliced cucumber with a splash of rice vinegar and salt.","Brown beef with garlic and ginger.","Stir in soy sauce, sugar and sesame oil; simmer 2 minutes.","Serve over rice with cucumbers and spring onions."]'::jsonb, 10, 15, 4, 'Korean', 'Omnivore', 560, ARRAY['lunch', 'dinner']::text[]),
  ('Chicken Tikka Masala', 'Charred yogurt-marinated chicken in a creamy spiced tomato sauce.', '["1.5 lb chicken thighs","1/2 cup plain yogurt","2 tbsp tikka masala paste","1 onion","3 cloves garlic","1 can crushed tomatoes","1/2 cup cream","Basmati rice","Cilantro"]'::jsonb, '["Marinate chicken in yogurt and 1 tbsp paste for 15 minutes.","Sear chicken until charred; set aside.","Soften onion and garlic, add remaining paste and tomatoes; simmer 10 minutes.","Stir in cream and chicken; simmer 8 minutes. Serve with rice and cilantro."]'::jsonb, 20, 30, 4, 'Indian', 'Omnivore', 580, ARRAY['dinner']::text[]),
  ('Pork Carnitas Bowls', 'Crispy citrus-braised pork with black beans, rice and pico de gallo.', '["3 lb pork shoulder","1 orange","2 limes","1 onion","4 cloves garlic","2 tsp cumin","1 tsp oregano","Rice and black beans","Pico de gallo"]'::jsonb, '["Season pork with cumin, oregano, salt and pepper.","Braise with orange and lime juice, onion and garlic, covered, at 325°F for 2 hours.","Shred, then crisp under the broiler for 5 minutes.","Serve over rice and beans with pico de gallo."]'::jsonb, 15, 120, 6, 'Mexican', 'Omnivore', 620, ARRAY['dinner']::text[]),
  ('Chicken Caesar Wraps', 'Grilled chicken, crisp romaine and parmesan in a creamy Caesar wrap.', '["2 chicken breasts","1 head romaine","1/3 cup Caesar dressing","1/4 cup parmesan","4 large tortillas","Lemon"]'::jsonb, '["Season and grill chicken 6 minutes per side; slice.","Toss chopped romaine with dressing, parmesan and a squeeze of lemon.","Fill tortillas with salad and chicken; roll tightly and halve."]'::jsonb, 15, 12, 4, 'American', 'Omnivore', 470, ARRAY['lunch']::text[]),
  ('Beef and Vegetable Chili', 'Hearty weeknight chili loaded with beans and vegetables.', '["1 lb lean ground beef","1 onion","1 bell pepper","1 zucchini","2 cans kidney beans","1 can crushed tomatoes","2 tbsp chili powder","1 tsp cumin","Cheddar and sour cream"]'::jsonb, '["Brown beef with diced onion and pepper.","Add zucchini, spices, tomatoes and beans with 1 cup water.","Simmer 30 minutes, stirring occasionally.","Top with cheddar and sour cream."]'::jsonb, 15, 40, 6, 'American', 'Omnivore', 510, ARRAY['dinner']::text[]),
  ('Lemon Garlic Chicken Orzo', 'One-pot orzo with chicken, spinach and a bright lemon finish.', '["1.25 lb chicken breast, cubed","1 1/2 cups orzo","3 cups chicken broth","3 cloves garlic","2 cups spinach","1 lemon","1/4 cup parmesan"]'::jsonb, '["Brown chicken in olive oil; add garlic for 30 seconds.","Add orzo and broth; simmer, stirring, 10–12 minutes.","Stir in spinach, lemon zest and juice, and parmesan."]'::jsonb, 10, 25, 4, 'Mediterranean', 'Omnivore', 530, ARRAY['lunch', 'dinner']::text[]),
  ('Breakfast Burritos', 'Make-ahead burritos with eggs, sausage, potatoes and cheese.', '["8 eggs","1/2 lb breakfast sausage","2 cups diced potatoes","1 cup shredded cheddar","6 large tortillas","Salsa"]'::jsonb, '["Crisp potatoes in a skillet, about 12 minutes; set aside.","Brown sausage, then scramble in the eggs.","Fill tortillas with potatoes, eggs, sausage and cheese; roll.","Serve with salsa, or wrap and freeze for busy mornings."]'::jsonb, 15, 20, 6, 'Mexican', 'Omnivore', 520, ARRAY['breakfast']::text[]),
  ('Thai Basil Chicken', 'Fast stir-fry of chicken, chilies and holy basil over jasmine rice.', '["1 lb ground chicken","4 cloves garlic","2 Thai chilies","2 tbsp oyster sauce","1 tbsp soy sauce","1 tsp sugar","1 cup Thai basil","Jasmine rice","Fried eggs (optional)"]'::jsonb, '["Stir-fry garlic and chilies 30 seconds.","Add chicken and cook until browned.","Add sauces and sugar; toss in basil until wilted.","Serve over rice, topped with a fried egg if you like."]'::jsonb, 10, 10, 4, 'Thai', 'Omnivore', 480, ARRAY['lunch', 'dinner']::text[]),
  ('Lemon Herb Baked Cod', 'Flaky cod baked with lemon, garlic and herbs alongside roasted asparagus.', '["4 cod fillets","1 lb asparagus","2 tbsp butter, melted","2 cloves garlic","1 lemon","2 tbsp parsley","Salt and pepper"]'::jsonb, '["Heat oven to 400°F.","Arrange cod and asparagus on a sheet pan.","Brush with butter mixed with garlic, lemon zest and parsley.","Bake 12–15 minutes; finish with lemon juice."]'::jsonb, 10, 15, 4, 'Mediterranean', 'Pescatarian', 310, ARRAY['lunch', 'dinner']::text[]),
  ('Fish Tacos with Lime Slaw', 'Crispy seasoned white fish with a tangy cabbage slaw.', '["1 lb tilapia or cod","1 tsp chili powder","1 tsp cumin","8 corn tortillas","3 cups shredded cabbage","1/4 cup Greek yogurt","2 limes","Cilantro"]'::jsonb, '["Toss cabbage with yogurt, lime juice and salt.","Season fish with spices and sear 3 minutes per side; flake.","Warm tortillas and fill with fish and slaw; top with cilantro."]'::jsonb, 15, 10, 4, 'Mexican', 'Pescatarian', 440, ARRAY['lunch', 'dinner']::text[]),
  ('Garlic Butter Shrimp & Rice', 'Juicy shrimp in garlic butter over fluffy rice with green beans.', '["1 lb shrimp","3 tbsp butter","4 cloves garlic","1/4 tsp red pepper flakes","1 lemon","2 cups cooked rice","8 oz green beans"]'::jsonb, '["Steam green beans 5 minutes.","Melt butter, add garlic and pepper flakes.","Cook shrimp 2 minutes per side; finish with lemon.","Serve over rice with green beans."]'::jsonb, 10, 15, 4, 'American', 'Pescatarian', 470, ARRAY['lunch', 'dinner']::text[]),
  ('Mediterranean Tuna Salad', 'No-mayo tuna salad with white beans, olives and herbs.', '["2 cans tuna in olive oil","1 can cannellini beans","1/4 cup kalamata olives","1/4 red onion","1 cup cherry tomatoes","Parsley","1 lemon"]'::jsonb, '["Drain tuna and beans.","Combine with chopped olives, onion, tomatoes and parsley.","Dress with lemon juice and a drizzle of the tuna oil; season."]'::jsonb, 10, 0, 2, 'Mediterranean', 'Pescatarian', 360, ARRAY['lunch']::text[]),
  ('Miso Glazed Salmon', 'Caramelized miso salmon with sesame broccoli.', '["4 salmon fillets","2 tbsp white miso","1 tbsp honey","1 tbsp rice vinegar","1 tsp soy sauce","1 head broccoli","Sesame seeds"]'::jsonb, '["Whisk miso, honey, vinegar and soy sauce.","Brush over salmon; broil 8–10 minutes until caramelized.","Roast broccoli at 425°F for 15 minutes; sprinkle with sesame."]'::jsonb, 10, 15, 4, 'Japanese', 'Pescatarian', 520, ARRAY['lunch', 'dinner']::text[]),
  ('Shrimp Pad See Ew', 'Wide rice noodles stir-fried with shrimp, Chinese broccoli and egg.', '["8 oz wide rice noodles","12 oz shrimp","2 eggs","4 cups Chinese broccoli","3 tbsp dark soy sauce","1 tbsp oyster sauce","1 tsp sugar","2 cloves garlic"]'::jsonb, '["Soak noodles until pliable.","Sear shrimp with garlic; push aside and scramble eggs.","Add broccoli and noodles with sauces and sugar.","Toss over high heat 2–3 minutes until glossy."]'::jsonb, 15, 10, 4, 'Thai', 'Pescatarian', 540, ARRAY['lunch', 'dinner']::text[]),
  ('Smoked Salmon Bagel Board', 'Bagels with smoked salmon, herbed cream cheese and fresh toppings.', '["4 whole-grain bagels","8 oz smoked salmon","1/2 cup cream cheese","1 tbsp dill","Capers","Red onion","Cucumber","Lemon"]'::jsonb, '["Stir dill into cream cheese.","Toast bagels.","Spread cream cheese and layer salmon, cucumber, onion and capers.","Finish with lemon and black pepper."]'::jsonb, 10, 0, 4, 'American', 'Pescatarian', 430, ARRAY['breakfast']::text[]),
  ('Spinach & Ricotta Stuffed Shells', 'Jumbo pasta shells filled with ricotta and spinach, baked in marinara.', '["20 jumbo pasta shells","15 oz ricotta","2 cups spinach, chopped","1 egg","1 cup mozzarella","1/2 cup parmesan","24 oz marinara"]'::jsonb, '["Boil shells until just al dente.","Mix ricotta, spinach, egg and half the cheeses.","Fill shells and arrange over marinara in a baking dish.","Top with remaining cheese; bake at 375°F for 25 minutes."]'::jsonb, 20, 30, 6, 'Italian', 'Vegetarian', 520, ARRAY['dinner']::text[]),
  ('Veggie Fried Rice', 'Day-old rice fried with eggs, peas, carrots and soy.', '["3 cups cold cooked rice","3 eggs","1 cup peas and carrots","3 spring onions","2 cloves garlic","3 tbsp soy sauce","1 tsp sesame oil"]'::jsonb, '["Scramble eggs in a hot wok; set aside.","Stir-fry garlic and vegetables 2 minutes.","Add rice and soy sauce; fry until hot and slightly crisp.","Fold in eggs, spring onions and sesame oil."]'::jsonb, 10, 10, 4, 'Chinese', 'Vegetarian', 420, ARRAY['lunch', 'dinner']::text[]),
  ('Shakshuka', 'Eggs poached in a spiced tomato and pepper sauce.', '["6 eggs","1 can crushed tomatoes","1 red bell pepper","1 onion","3 cloves garlic","1 tsp cumin","1 tsp smoked paprika","Feta","Crusty bread"]'::jsonb, '["Soften onion and pepper; add garlic and spices.","Add tomatoes and simmer 10 minutes.","Make wells and crack in eggs; cover and cook 6–8 minutes.","Crumble feta on top; serve with bread."]'::jsonb, 10, 25, 4, 'Middle Eastern', 'Vegetarian', 320, ARRAY['breakfast', 'dinner']::text[]),
  ('Margherita Flatbread', 'Crisp flatbread with tomato, fresh mozzarella and basil.', '["2 naan or flatbreads","1/2 cup pizza sauce","6 oz fresh mozzarella","1 cup cherry tomatoes","Fresh basil","Olive oil"]'::jsonb, '["Heat oven to 450°F.","Spread sauce over flatbreads; top with mozzarella and halved tomatoes.","Bake 10–12 minutes until bubbling.","Finish with basil and olive oil."]'::jsonb, 10, 12, 2, 'Italian', 'Vegetarian', 460, ARRAY['lunch', 'dinner']::text[]),
  ('Greek Yogurt Parfait', 'Layers of Greek yogurt, granola, berries and honey.', '["1 cup Greek yogurt","1/3 cup granola","1/2 cup mixed berries","1 tbsp honey","1 tbsp chia seeds"]'::jsonb, '["Layer yogurt, berries and granola in a glass.","Drizzle with honey and sprinkle with chia."]'::jsonb, 5, 0, 1, 'American', 'Vegetarian', 320, ARRAY['breakfast', 'snack']::text[]),
  ('Black Bean Quesadillas', 'Cheesy quesadillas with black beans, corn and peppers.', '["1 can black beans","1 cup corn","1 bell pepper","1 1/2 cups shredded cheese","1 tsp cumin","8 tortillas","Salsa and guacamole"]'::jsonb, '["Sauté pepper and corn with cumin; stir in mashed beans.","Fill tortillas with beans and cheese; fold.","Cook in a dry skillet 3 minutes per side until golden.","Cut into wedges; serve with salsa and guacamole."]'::jsonb, 10, 10, 4, 'Mexican', 'Vegetarian', 480, ARRAY['lunch', 'dinner']::text[]),
  ('Mushroom Risotto', 'Creamy arborio rice with sautéed mushrooms and parmesan.', '["1 1/2 cups arborio rice","12 oz mushrooms","1 shallot","5 cups vegetable broth, warm","1/2 cup white wine (optional)","1/2 cup parmesan","2 tbsp butter","Thyme"]'::jsonb, '["Sauté mushrooms until golden; set aside.","Soften shallot, add rice and toast 1 minute; add wine.","Add broth a ladle at a time, stirring, for about 20 minutes.","Stir in mushrooms, butter, parmesan and thyme."]'::jsonb, 10, 30, 4, 'Italian', 'Vegetarian', 510, ARRAY['dinner']::text[]),
  ('Caprese Pasta Salad', 'Pasta tossed with tomatoes, mozzarella, basil and balsamic.', '["12 oz rotini","2 cups cherry tomatoes","8 oz mozzarella pearls","1 cup basil","3 tbsp olive oil","2 tbsp balsamic glaze"]'::jsonb, '["Cook pasta, rinse under cold water and drain.","Toss with tomatoes, mozzarella, basil and olive oil.","Season and drizzle with balsamic glaze."]'::jsonb, 10, 10, 6, 'Italian', 'Vegetarian', 430, ARRAY['lunch']::text[]),
  ('Vegan Buddha Bowl', 'Roasted chickpeas and sweet potato over quinoa with tahini dressing.', '["1 can chickpeas","1 large sweet potato","1 cup quinoa","2 cups kale","1 avocado","1/4 cup tahini","1 lemon","1 tsp smoked paprika"]'::jsonb, '["Roast cubed sweet potato and chickpeas with paprika at 425°F for 25 minutes.","Cook quinoa.","Massage kale with a little lemon and salt.","Whisk tahini, lemon and water; assemble bowls and drizzle."]'::jsonb, 15, 30, 4, 'American', 'Vegan', 540, ARRAY['lunch', 'dinner']::text[]),
  ('Red Lentil Dal', 'Silky spiced lentils finished with a sizzling cumin tadka.', '["1 1/2 cups red lentils","1 onion","3 cloves garlic","1 tbsp ginger","1 tsp turmeric","1 can coconut milk","2 tsp cumin seeds","Cilantro","Rice or naan"]'::jsonb, '["Simmer lentils with turmeric in 4 cups water for 15 minutes.","Sauté onion, garlic and ginger; add to lentils with coconut milk.","Sizzle cumin seeds in oil and pour over the dal.","Top with cilantro; serve with rice."]'::jsonb, 10, 25, 4, 'Indian', 'Vegan', 400, ARRAY['lunch', 'dinner']::text[]),
  ('Peanut Noodle Stir-Fry', 'Noodles and crunchy vegetables in a creamy peanut-lime sauce.', '["8 oz rice or soba noodles","1/3 cup peanut butter","3 tbsp soy sauce","2 tbsp lime juice","1 tbsp maple syrup","1 red bell pepper","2 carrots","2 cups snap peas","Crushed peanuts"]'::jsonb, '["Cook noodles; rinse.","Whisk peanut butter, soy sauce, lime, maple and warm water.","Stir-fry sliced vegetables 3 minutes.","Toss with noodles and sauce; top with peanuts."]'::jsonb, 15, 10, 4, 'Thai', 'Vegan', 560, ARRAY['lunch', 'dinner']::text[]),
  ('Tofu Scramble', 'Turmeric-spiced tofu scramble with peppers and spinach.', '["14 oz firm tofu","1/2 tsp turmeric","2 tbsp nutritional yeast","1/2 bell pepper","1 cup spinach","1/4 onion","Salt and black pepper"]'::jsonb, '["Sauté onion and pepper until soft.","Crumble in tofu with turmeric and nutritional yeast.","Cook 5 minutes, then fold in spinach until wilted."]'::jsonb, 5, 10, 2, 'American', 'Vegan', 290, ARRAY['breakfast']::text[]),
  ('Minestrone Soup', 'Classic Italian vegetable soup with beans and pasta.', '["1 onion","2 carrots","2 celery stalks","1 zucchini","1 can diced tomatoes","1 can cannellini beans","6 cups vegetable broth","1 cup small pasta","2 cups spinach"]'::jsonb, '["Sauté onion, carrot and celery 8 minutes.","Add zucchini, tomatoes, beans and broth; simmer 15 minutes.","Add pasta and cook until tender.","Stir in spinach; season."]'::jsonb, 15, 30, 6, 'Italian', 'Vegan', 330, ARRAY['lunch', 'dinner']::text[]),
  ('Chickpea Salad Sandwiches', 'Smashed chickpeas with crunchy celery and a lemony dressing.', '["2 cans chickpeas","2 celery stalks","1/4 red onion","3 tbsp vegan mayo","1 tbsp Dijon","1 lemon","8 slices whole-grain bread","Lettuce and tomato"]'::jsonb, '["Mash chickpeas with a fork.","Mix in diced celery and onion, mayo, Dijon and lemon.","Build sandwiches with lettuce and tomato."]'::jsonb, 10, 0, 4, 'American', 'Vegan', 410, ARRAY['lunch']::text[]),
  ('Stuffed Bell Peppers', 'Peppers filled with rice, black beans, corn and salsa.', '["4 bell peppers","1 cup cooked rice","1 can black beans","1 cup corn","1 cup salsa","1 tsp cumin","Avocado"]'::jsonb, '["Heat oven to 375°F; halve and seed the peppers.","Mix rice, beans, corn, salsa and cumin.","Fill peppers, cover with foil and bake 30 minutes.","Top with sliced avocado."]'::jsonb, 15, 35, 4, 'Mexican', 'Vegan', 380, ARRAY['dinner']::text[]),
  ('Coconut Chia Pudding', 'Make-ahead chia pudding with coconut milk and mango.', '["1/4 cup chia seeds","1 cup coconut milk","1 tbsp maple syrup","1/2 tsp vanilla","1 mango"]'::jsonb, '["Whisk chia, coconut milk, maple and vanilla.","Refrigerate at least 4 hours or overnight.","Top with diced mango."]'::jsonb, 5, 0, 2, 'American', 'Vegan', 300, ARRAY['breakfast', 'snack']::text[]),
  ('Zucchini Noodles with Pesto', 'Spiralized zucchini tossed with basil-walnut pesto and tomatoes.', '["3 zucchini, spiralized","2 cups basil","1/3 cup walnuts","1 clove garlic","1/3 cup olive oil","1 lemon","1 cup cherry tomatoes"]'::jsonb, '["Blend basil, walnuts, garlic, olive oil and lemon into a pesto.","Toss zucchini noodles with pesto.","Top with halved tomatoes and season."]'::jsonb, 15, 0, 2, 'Italian', 'Raw', 310, ARRAY['lunch', 'dinner']::text[]),
  ('Thai Mango Salad', 'Crunchy mango and vegetable salad with a lime-chili dressing.', '["2 firm mangoes","1 red bell pepper","1 cup shredded red cabbage","1 carrot","1/4 cup cilantro","2 limes","1 tbsp maple syrup","1 Thai chili","Cashews"]'::jsonb, '["Julienne mango, pepper and carrot.","Whisk lime juice, maple and minced chili.","Toss with cabbage and cilantro; top with cashews."]'::jsonb, 15, 0, 2, 'Thai', 'Raw', 260, ARRAY['lunch']::text[]),
  ('Green Power Smoothie Bowl', 'Thick spinach, banana and mango smoothie bowl with crunchy toppings.', '["1 frozen banana","1/2 cup frozen mango","1 cup spinach","1/2 cup almond milk","1 tbsp almond butter","Toppings: berries, hemp seeds, sliced kiwi"]'::jsonb, '["Blend banana, mango, spinach, almond milk and almond butter until thick.","Pour into a bowl and add toppings."]'::jsonb, 10, 0, 1, 'American', 'Raw', 340, ARRAY['breakfast']::text[]),
  ('Raw Energy Bites', 'No-bake date and nut bites for an easy snack.', '["1 cup pitted dates","1 cup almonds","2 tbsp cacao powder","2 tbsp chia seeds","1 tbsp almond butter","Pinch of sea salt"]'::jsonb, '["Pulse almonds in a food processor until coarse.","Add dates, cacao, chia, almond butter and salt; blend until sticky.","Roll into 12 balls and chill 30 minutes."]'::jsonb, 15, 0, 12, 'American', 'Raw', 180, ARRAY['snack']::text[]),
  ('Avocado Toast with Tomatoes', 'Smashed avocado on toasted sourdough with cherry tomatoes and chili flakes.', '["2 slices sourdough bread","1 ripe avocado","1 cup cherry tomatoes","1/2 lemon","Chili flakes","Salt and pepper"]'::jsonb, '["Toast the bread.","Mash avocado with lemon juice, salt and pepper.","Spread on toast and top with halved tomatoes and chili flakes."]'::jsonb, 8, 4, 2, 'American', 'Vegan', 340, ARRAY['breakfast']::text[]),
  ('Banana Oat Pancakes', 'Fluffy dairy-free pancakes made from oats and ripe banana.', '["1 cup rolled oats","2 ripe bananas","3/4 cup oat milk","1 tsp baking powder","1/2 tsp cinnamon","Maple syrup to serve"]'::jsonb, '["Blend oats, bananas, oat milk, baking powder and cinnamon until smooth.","Rest the batter 5 minutes.","Cook 1/4-cup portions in a lightly oiled pan, 2 minutes per side.","Serve with maple syrup."]'::jsonb, 10, 15, 2, 'American', 'Vegan', 380, ARRAY['breakfast']::text[]),
  ('Sweet Potato Breakfast Hash', 'Crispy sweet potato with peppers, onion and black beans.', '["1 large sweet potato","1 bell pepper","1/2 red onion","1 can black beans","1 tsp smoked paprika","Olive oil, salt, pepper"]'::jsonb, '["Dice sweet potato, pepper and onion.","Cook sweet potato in olive oil for 10 minutes until golden.","Add pepper, onion and paprika; cook 6 minutes.","Stir in rinsed beans until warm and season."]'::jsonb, 10, 20, 2, 'American', 'Vegan', 410, ARRAY['breakfast', 'lunch']::text[]),
  ('Spinach Feta Omelette', 'A quick three-egg omelette folded around wilted spinach and feta.', '["3 eggs","1 cup baby spinach","1/4 cup crumbled feta","1 tsp butter","Salt and pepper"]'::jsonb, '["Whisk eggs with salt and pepper.","Wilt spinach in butter, then pour in eggs.","Cook until nearly set, add feta and fold."]'::jsonb, 5, 8, 1, 'Mediterranean', 'Vegetarian', 360, ARRAY['breakfast']::text[]),
  ('Veggie Egg Muffins', 'Make-ahead egg cups loaded with peppers, spinach and cheese.', '["8 eggs","1 bell pepper","1 cup spinach","1/2 cup shredded cheddar","1/4 cup milk","Salt and pepper"]'::jsonb, '["Heat oven to 375°F and grease a muffin tin.","Whisk eggs, milk, salt and pepper.","Divide chopped vegetables and cheese between cups and pour over the egg.","Bake 18–20 minutes until set."]'::jsonb, 10, 20, 6, 'American', 'Vegetarian', 280, ARRAY['breakfast', 'snack']::text[]),
  ('Turkey Sausage Breakfast Skillet', 'Turkey sausage, potatoes and peppers topped with fried eggs.', '["12 oz turkey sausage","1 lb baby potatoes","1 bell pepper","1/2 onion","4 eggs","Olive oil, salt, pepper"]'::jsonb, '["Quarter potatoes and cook in olive oil for 12 minutes.","Add crumbled sausage, pepper and onion; cook through.","Make four wells and crack in the eggs.","Cover and cook until eggs are set."]'::jsonb, 10, 25, 4, 'American', 'Omnivore', 480, ARRAY['breakfast']::text[]),
  ('Salmon & Avocado Rice Cakes', 'Crisp rice cakes topped with smoked salmon, avocado and dill.', '["4 rice cakes","4 oz smoked salmon","1 avocado","Fresh dill","1/2 lemon","Black pepper"]'::jsonb, '["Mash avocado with lemon juice.","Spread on rice cakes.","Top with smoked salmon, dill and black pepper."]'::jsonb, 8, 0, 2, 'Scandinavian', 'Pescatarian', 320, ARRAY['breakfast', 'snack']::text[]),
  ('Raw Buckwheat Porridge', 'Soaked buckwheat blended with banana and topped with fresh fruit.', '["1 cup raw buckwheat groats, soaked overnight","1 banana","1/2 cup water","1 tsp cinnamon","1 cup fresh berries","2 tbsp hemp seeds"]'::jsonb, '["Drain and rinse the soaked buckwheat.","Blend with banana, water and cinnamon until creamy.","Top with berries and hemp seeds."]'::jsonb, 10, 0, 2, 'Raw', 'Raw', 330, ARRAY['breakfast']::text[]),
  ('Tropical Fruit & Coconut Bowl', 'Mango, pineapple and kiwi with coconut flakes and lime.', '["1 mango","1 cup pineapple","2 kiwis","2 tbsp coconut flakes","1 lime","Fresh mint"]'::jsonb, '["Dice all the fruit.","Toss with lime juice.","Top with coconut flakes and mint."]'::jsonb, 10, 0, 2, 'Raw', 'Raw', 290, ARRAY['breakfast', 'snack']::text[]),
  ('Hummus & Veggie Sticks', 'Creamy hummus with crunchy carrot, cucumber and pepper sticks.', '["1/2 cup hummus","2 carrots","1 cucumber","1 bell pepper"]'::jsonb, '["Cut vegetables into sticks.","Serve with hummus for dipping."]'::jsonb, 10, 0, 2, 'Mediterranean', 'Vegan', 210, ARRAY['snack']::text[]),
  ('Apple Slices with Almond Butter', 'Crisp apple wedges with almond butter and a pinch of cinnamon.', '["1 apple","2 tbsp almond butter","Pinch of cinnamon"]'::jsonb, '["Core and slice the apple.","Serve with almond butter sprinkled with cinnamon."]'::jsonb, 5, 0, 1, 'American', 'Vegan', 220, ARRAY['snack']::text[]),
  ('Spiced Roasted Chickpeas', 'Crunchy oven-roasted chickpeas with smoked paprika.', '["1 can chickpeas","1 tbsp olive oil","1 tsp smoked paprika","1/2 tsp garlic powder","Salt"]'::jsonb, '["Heat oven to 400°F.","Dry the rinsed chickpeas well and toss with oil and spices.","Roast 25–30 minutes, shaking halfway, until crunchy."]'::jsonb, 5, 30, 4, 'Mediterranean', 'Vegan', 190, ARRAY['snack']::text[]),
  ('Edamame with Sea Salt', 'Steamed edamame pods with flaky salt and lemon.', '["2 cups frozen edamame in pods","Flaky sea salt","1/2 lemon"]'::jsonb, '["Boil or steam edamame for 5 minutes.","Drain and toss with salt and a squeeze of lemon."]'::jsonb, 2, 5, 2, 'Japanese', 'Vegan', 190, ARRAY['snack']::text[]),
  ('Cottage Cheese & Pineapple', 'High-protein cottage cheese with juicy pineapple.', '["3/4 cup cottage cheese","1/2 cup pineapple chunks","1 tsp honey"]'::jsonb, '["Spoon cottage cheese into a bowl.","Top with pineapple and a drizzle of honey."]'::jsonb, 3, 0, 1, 'American', 'Vegetarian', 200, ARRAY['snack', 'breakfast']::text[]),
  ('Turkey & Cheese Roll-Ups', 'Sliced turkey rolled with cheese, cucumber and mustard.', '["4 slices deli turkey","2 slices Swiss cheese","1/2 cucumber","1 tsp Dijon mustard"]'::jsonb, '["Lay out turkey and spread with mustard.","Add half a cheese slice and a cucumber strip to each.","Roll up tightly."]'::jsonb, 5, 0, 1, 'American', 'Omnivore', 230, ARRAY['snack']::text[]),
  ('Guacamole with Veggie Chips', 'Fresh guacamole served with sliced jicama, radish and cucumber.', '["2 avocados","1/2 red onion","1 tomato","1 lime","Cilantro","1 small jicama","4 radishes"]'::jsonb, '["Mash avocados with lime juice and salt.","Fold in diced onion, tomato and cilantro.","Slice jicama, radishes and serve alongside."]'::jsonb, 10, 0, 2, 'Mexican', 'Raw', 240, ARRAY['snack']::text[])
), updated AS (
  UPDATE recipes r SET meal_types = v.meal_types FROM v WHERE r.created_by IS NULL AND r.title = v.title
)
INSERT INTO recipes (title, description, ingredients, steps, prep_time_minutes, cook_time_minutes, servings, cuisine, diet_type, calories, meal_types)
SELECT v.* FROM v
WHERE NOT EXISTS (SELECT 1 FROM recipes r WHERE r.created_by IS NULL AND r.title = v.title);
